// fix-school-app-v24.5.cjs — Private School App (SSSPS Info) v24.5 DELTA fix
// RUN: place this file in the project root (next to package.json) and run:
//   node fix-school-app-v24.5.cjs
// THIS IS THE v24.5-ONLY SCRIPT. It only works on a project where v24.4
// was already applied (package.json says 24.4.0). If you have NOT run v24.4
// yet, run the v24.4 script first (fix-school-app-v24.4.cjs), then this one.
// It backs up every file it changes to <file>.bak first, then applies the
// v24.5 files, runs npm install (to sync package-lock.json), then typecheck
// (npm run lint), tests (npm test) and build (npm run build).
// Safe to run twice: the second run reports everything already applied.
// WHAT v24.5 FIXES:
//  - Cloudflare build kept failing before the build command even ran:
//    "Plugin bun's list-all callback script failed ... curl: (22) ... 403".
//    Cloudflare tried to look up the list of available Bun versions and the
//    server refused (403). This fix pins Bun to version 1.4.4 in
//    package.json ("packageManager": "bun@1.4.4"), so Cloudflare installs
//    that exact version instead of asking for the list. Per Cloudflare's
//    own docs, the packageManager field only pins the version — the lockfile
//    (package-lock.json) still decides that npm installs the dependencies,
//    so nothing else changes.
//  - Version History gets a v24.5 entry so you can see the fix arrived.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execSync } = require('child_process');

const ROOT = process.cwd();
function log(tag, msg) { console.log('[' + tag + '] ' + msg); }
function sha1(buf) { return crypto.createHash('sha1').update(buf).digest('hex'); }
function run(cmd, label) {
  log('RUN', label + ': ' + cmd);
  try {
    execSync(cmd, { cwd: ROOT, stdio: 'inherit', shell: true });
    log('OK', label + ' passed');
    return true;
  } catch (e) {
    log('FAIL', label + ' failed (see output above)');
    return false;
  }
}

// Sanity check: are we in the school app project root?
if (!fs.existsSync(path.join(ROOT, 'src', 'pages', 'Admin.tsx')) || !fs.existsSync(path.join(ROOT, 'firestore.rules'))) {
  console.error('[ERROR] Project root not found. Run this script from the project folder (the one with package.json, src/pages/Admin.tsx and firestore.rules).');
  process.exit(1);
}

// Guard: this delta only makes sense on top of v24.4.
let pkgVersion = null;
try { pkgVersion = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8')).version; } catch (e) {}
if (pkgVersion !== '24.4.0' && pkgVersion !== '24.5.0') {
  console.error('[ERROR] This is the v24.5-ONLY script and your project is at version ' + (pkgVersion || '(unknown)') + ', not v24.4.');
  console.error('        Run the v24.4 script first (fix-school-app-v24.4.cjs), then run this one.');
  process.exit(1);
}
if (pkgVersion === '24.5.0') {
  console.log('[NOTE] package.json already says 24.5.0 — checking whether all v24.5 files are in place...');
}

const FILES = [{"rel":"package.json","origSha1":"d96727a13f40ec8ae914897bce5a8ff115787e86","b64":""},{"rel":"package-lock.json","origSha1":"b38392e644c4ea3b177876e509709aa33e906a22","b64":""},{"rel":"src/constants.ts","origSha1":"d61a06079e2f64e435c96bacc313049a3737f813","b64":""},{"rel":"src/data/versions.ts","origSha1":"d388c3be30aacefd22332a73f10314fa7362baf0","b64":""}];

let applied = 0, skipped = 0;
const warnings = [];
for (const f of FILES) {
  const target = path.join(ROOT, f.rel);
  const targetBuf = Buffer.from(f.b64, 'base64');
  const targetSha = sha1(targetBuf);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  if (fs.existsSync(target)) {
    const cur = fs.readFileSync(target);
    if (sha1(cur) === targetSha) { skipped++; continue; }
    if (f.origSha1 && sha1(cur) !== f.origSha1) {
      warnings.push(f.rel + ' (locally modified since the Zip - backed up to .bak, new version applied)');
    }
    const bak = target + '.bak';
    if (!fs.existsSync(bak)) fs.copyFileSync(target, bak);
  }
  fs.writeFileSync(target, targetBuf);
  applied++;
  log('APPLY', f.rel);
}
console.log('---');
console.log('Applied: ' + applied + ' | Already applied: ' + skipped + ' | Deleted: 0 | Delete skipped: 0');
if (warnings.length) {
  console.log('[WARN] These files differed from the Zip version (your own edits). They were backed up to .bak before applying:');
  for (const w of warnings) console.log('  - ' + w);
}
console.log('--- install + typecheck + tests + build ---');
const installOk = run('npm install', 'install');
const lintOk = installOk && run('npm run lint', 'typecheck');
const testOk = lintOk && run('npm test', 'tests');
const buildOk = testOk && run('npm run build', 'build');
console.log('---');
if (installOk && lintOk && testOk && buildOk) {
  console.log('[DONE] v24.5 applied. Install + typecheck + tests + build passed. Start the app with: npm run dev');
  console.log('[NOTE] Next: push to GitHub (node push-school-app.cjs) so Cloudflare rebuilds with the pinned Bun version. Then check the Version History showing v24.5.');
  // Cleanup (only on full success, so *.bak backups stay available if anything failed):
  // remove the old v24.4 fix script and stale *.bak files so the folder stays tidy.
  const OLD_SCRIPTS = ['fix-school-app-v24.4.cjs'];
  let cleanedScripts = 0, cleanedBak = 0;
  for (const name of OLD_SCRIPTS) {
    const p = path.join(ROOT, name);
    if (fs.existsSync(p)) { fs.unlinkSync(p); cleanedScripts++; log('CLEAN', name); }
  }
  const SKIP_DIRS = new Set(['node_modules', 'dist', '.git']);
  (function walkClean(dir) {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      if (e.isDirectory()) { if (!SKIP_DIRS.has(e.name)) walkClean(path.join(dir, e.name)); }
      else if (e.name.endsWith('.bak')) { fs.unlinkSync(path.join(dir, e.name)); cleanedBak++; }
    }
  })(ROOT);
  console.log('[CLEAN] Removed ' + cleanedScripts + ' old script(s) and ' + cleanedBak + ' .bak backup file(s).');
} else {
  console.log('[DONE WITH WARNINGS] Files were applied, but install/typecheck/tests/build did not fully pass. Your originals are in *.bak files. Check the errors above.');
}
